package octal

import "errors"

// ParseOctal converts an octal number, represented as a string, to its
// decimal equivalent using first principles: each digit is weighted by a
// power of 8 and the values are summed.
//
// Invalid input (any character outside '0'-'7', or an empty string) is
// treated as octal 0: it returns 0 along with an error.
func ParseOctal(input string) (int64, error) {
	if input == "" {
		return 0, errors.New("invalid octal input: empty string")
	}

	// Accumulate from left to right (Horner's method), which is equivalent
	// to summing each digit times its power of 8:
	//   233 (octal) = ((2*8 + 3)*8 + 3) = 155 (decimal)
	var result int64
	for i := 0; i < len(input); i++ {
		c := input[i]
		if c < '0' || c > '7' {
			return 0, errors.New("invalid octal input: digit must be 0-7")
		}
		result = result*8 + int64(c-'0')
	}
	return result, nil
}

